# Versions-Registry — die AKTIVE Version steht an erster Stelle
WATCHLIST_VERSIONS: dict[str, str] = {
    "Q3 2026": RAW_WATCHLIST_Q3_2026,
    "Q1 2026": RAW_WATCHLIST_Q1_2026,
}
DEFAULT_VERSION = "Q3 2026"

# Rückwärtskompatibilität (alte Importe/Referenzen)
RAW_WATCHLIST = RAW_WATCHLIST_Q3_2026


def _normalize_ticker(raw: str) -> str:
    """Entfernt Exchange-Prefix und normalisiert Ticker für yfinance."""
    ticker = raw.strip()
    if ":" in ticker:
        ticker = ticker.split(":", 1)[1]
    # yfinance verwendet BRK-B statt BRK.B
    ticker = ticker.replace(".", "-")
    return ticker


def parse_watchlist(version: str = DEFAULT_VERSION) -> dict:
    """Parst die Watchlist einer Version in ein Dict: {Sektor: [Ticker, ...]}"""
    raw = WATCHLIST_VERSIONS.get(version, RAW_WATCHLIST_Q3_2026)
    sectors = {}
    current_sector = None

    parts = raw.split(",")
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if part.startswith("###"):
            current_sector = part.lstrip("#").strip()
            sectors[current_sector] = []
        elif current_sector and ":" in part:
            ticker = _normalize_ticker(part)
            if ticker not in sectors[current_sector]:
                sectors[current_sector].append(ticker)

    return sectors


def get_all_tickers(version: str = DEFAULT_VERSION) -> list[str]:
    """Gibt alle Ticker einer Version zurück (dedupliziert, Reihenfolge erhalten)."""
    watchlist = parse_watchlist(version)
    all_tickers = []
    seen = set()
    for tickers in watchlist.values():
        for t in tickers:
            if t not in seen:
                all_tickers.append(t)
                seen.add(t)
    return all_tickers


def get_sector_for_ticker(ticker: str) -> str:
    """
    Gibt den Sektor für einen Ticker zurück.
    Sucht zuerst in der aktiven Version, dann in den älteren Versionen —
    so behalten Depot-/Trade-Positionen aus früheren Listen ihren Sektor.
    """
    for version in WATCHLIST_VERSIONS:
        for sector, tickers in parse_watchlist(version).items():
            if ticker in tickers:
                return sector
    return "Unbekannt"


